$('cancelReply').onclick=()=>{replyingTo=null;$('replyDraft').hidden=true};function updateMentionSuggestions(){const input=$('input'),before=input.value.slice(0,input.selectionStart),match=before.match(/(?:^|\s)@([^@\s]*)$/),panel=$('mentionChoices');panel.replaceChildren();if(!match){panel.hidden=true;return}const options=people.filter(p=>p.id!==me&&p.name.toLowerCase().includes(match[1].toLowerCase())).slice(0,8);if(!options.length){panel.hidden=true;return}for(const p of options){const b=document.createElement('button');b.type='button';b.textContent='@'+p.name;b.onclick=()=>{const start=input.selectionStart,from=before.length-match[0].length+(match[0].startsWith(' ')?1:0);input.setRangeText('@'+p.name+' ',from,start,'end');if(!selectedMentions.includes(p.id))selectedMentions.push(p.id);panel.hidden=true;input.focus()};panel.append(b)}panel.hidden=false} $('input').addEventListener('input',updateMentionSuggestions);$('input').addEventListener('click',updateMentionSuggestions);

let blockedMembers=[];s.on('bannedMembers',list=>{blockedMembers=list||[];renderModeration()});s.on('removedFromCouncil',d=>{alert(d.banned?'تم حظرك من مجلس سارة':'تم إخراجك من مجلس سارة');location.reload()});function renderModeration(){if(!isAdmin)return;const box=$('moderationMembers');box.replaceChildren();for(const p of people.filter(p=>p.id!==me)){const row=document.createElement('div');row.className='moderationRow';const name=document.createElement('span');name.textContent=p.name;row.append(name);if(isPrimary&&!p.owner){const ownerBtn=document.createElement('button');ownerBtn.type='button';ownerBtn.textContent='👑 تعيين أونر';ownerBtn.onclick=()=>{if(confirm('تمنح '+p.name+' صلاحيات أونر كاملة مثلك؟'))s.emit('grantOwner',{id:p.id})};row.append(ownerBtn)}if(isPrimary&&p.owner&&!p.primary){const revoke=document.createElement('button');revoke.type='button';revoke.textContent='🗑 سحب صلاحية الأونر';revoke.style.cssText='background:#641326;color:white;border:1px solid #ff637c';revoke.onclick=()=>{if(confirm('تأكيد سحب صلاحيات الإدارة من '+p.name+'؟'))s.emit('revokeOwner',{id:p.id})};row.append(revoke)}for(const [label,action] of [['طرد','kick'],['حظر','ban']]){const b=document.createElement('button');b.type='button';b.textContent=label;b.onclick=()=>{if(confirm(action==='ban'?'حظر '+p.name+' من المجلس؟':'طرد '+p.name+' من المجلس؟'))s.emit('moderateMember',{id:p.id,action})};row.append(b)}box.append(row)}const banned=$('bannedMembers');banned.replaceChildren();for(const p of blockedMembers){const row=document.createElement('div');row.className='moderationRow';const label=document.createElement('span');label.textContent=p.name;const btn=document.createElement('button');btn.type='button';btn.textContent='فك الحظر';btn.onclick=()=>s.emit('moderateMember',{id:p.id,action:'unban'});row.append(label,btn);banned.append(row)}}

async function prepareAudioAttachment(f){const ext=(f.name.split('.').pop()||'').toLowerCase();const mime={mp3:'audio/mpeg',m4a:'audio/mp4',ogg:'audio/ogg',webm:'audio/webm'}[ext]||({'audio/mpeg':'audio/mpeg','audio/mp4':'audio/mp4','audio/ogg':'audio/ogg','audio/webm':'audio/webm'}[f.type]);if(!mime)throw Error('صيغة الصوت غير مدعومة. استخدم MP3 أو M4A أو OGG أو WebM');if(f.size>4000000)throw Error('حجم الصوت لازم 4 ميجابايت أو أقل');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('تعذر قراءة الصوت'));reader.readAsDataURL(new Blob([f],{type:mime}))});if(typeof data!=='string'||data.length>5600000)throw Error('حجم الصوت كبير');voice=data;$('voicePreview').src=voice;$('voiceDraft').hidden=false;toast('الصوت جاهز، اضغط إرسال')}
$('uploadAudioButton').onclick=()=>$('audioFile').click();$('audioFile').onchange=async e=>{const f=e.target.files?.[0];e.target.value='';if(!f)return;const ext=(f.name.split('.').pop()||'').toLowerCase();const mime={mp3:'audio/mpeg',m4a:'audio/mp4',ogg:'audio/ogg',webm:'audio/webm'}[ext];if(!mime)return toast('اختر ملف MP3 أو M4A أو OGG أو WebM');if(f.size>4000000)return toast('الملف الصوتي كبير، الحد الأقصى 4 ميجابايت');try{const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('تعذر قراءة الملف'));reader.readAsDataURL(new Blob([f],{type:mime}))});if(typeof data!=='string'||data.length>5600000)throw Error('الملف الصوتي كبير');voice=data;$('voicePreview').src=voice;$('voiceDraft').hidden=false;toast('الصوت جاهز، استمع له ثم اضغط إرسال')}catch(err){toast(err.message||'تعذر تجهيز الصوت')}};
let voiceRecorder=null,voiceStream=null,voiceParts=[],voiceTimer=null;const recordButton=$('recordVoice');function stopVoiceTracks(){if(voiceStream){voiceStream.getTracks().forEach(t=>t.stop());voiceStream=null}clearTimeout(voiceTimer)}recordButton.onclick=async()=>{if(voiceRecorder?.state==='recording'){voiceRecorder.stop();recordButton.textContent='🎙️';return}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)return toast('المتصفح لا يدعم التسجيل الصوتي');try{voiceStream=await navigator.mediaDevices.getUserMedia({audio:true});const mime=['audio/webm;codecs=opus','audio/mp4','audio/webm','audio/ogg'].find(x=>MediaRecorder.isTypeSupported(x));voiceParts=[];voiceRecorder=new MediaRecorder(voiceStream,mime?{mimeType:mime,audioBitsPerSecond:32000}:undefined);voiceRecorder.ondataavailable=e=>{if(e.data.size)voiceParts.push(e.data)};voiceRecorder.onstop=async()=>{stopVoiceTracks();recordButton.textContent='🎙️';const blob=new Blob(voiceParts,{type:voiceRecorder.mimeType||'audio/webm'});if(blob.size>2400000)return toast('التسجيل كبير، سجل رسالة أقصر');const reader=new FileReader();reader.onload=()=>{voice=reader.result;$('voicePreview').src=voice;$('voiceDraft').hidden=false;};reader.readAsDataURL(blob)};voiceRecorder.start();recordButton.textContent='⏹️';voiceTimer=setTimeout(()=>{if(voiceRecorder?.state==='recording')voiceRecorder.stop()},45000)}catch(e){stopVoiceTracks();toast('تعذر تشغيل المايك، تأكد من السماح للتسجيل')}};$('voiceCancel').onclick=()=>{voice=null;$('voiceDraft').hidden=true;$('voicePreview').removeAttribute('src')};$('voiceSend').onclick=()=>{if(!voice)return;send()};


/* Multiplayer Connect Four — state and moves verified by server */
let c4=null,c4Audio=null,c4SoundOn=localStorage.getItem('saraC4Sound')!=='off',c4Previous=null;
function c4Tone(freq,duration=0.11,delay=0,type='sine',volume=0.085){if(!c4SoundOn||!c4Audio)return;const t=c4Audio.currentTime+delay,o=c4Audio.createOscillator(),g=c4Audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,t);g.gain.setValueAtTime(0.001,t);g.gain.exponentialRampToValueAtTime(volume,t+0.015);g.gain.exponentialRampToValueAtTime(0.001,t+duration);o.connect(g);g.connect(c4Audio.destination);o.start(t);o.stop(t+duration+0.015)}
function c4Play(kind){try{if(kind==='drop'){c4Tone(460,.09,0,'triangle');c4Tone(260,.14,.07,'triangle')}else if(kind==='turn'){c4Tone(620,.09);c4Tone(830,.12,.12)}else if(kind==='win'){[523,659,784,1047].forEach((n,i)=>c4Tone(n,.25,i*.15,'sine',.1))}else if(kind==='draw'){c4Tone(450,.16);c4Tone(350,.24,.19)}else if(kind==='start'){c4Tone(440,.12);c4Tone(660,.15,.14)}}catch{}}
function c4EnableAudio(){try{const AC=window.AudioContext||window.webkitAudioContext;if(!c4Audio&&AC)c4Audio=new AC();if(c4Audio?.state==='suspended')c4Audio.resume()}catch{}}
function c4UpdateSoundButton(){const b=$('c4Sound');b.textContent=c4SoundOn?'🔊 الصوت شغال':'🔇 الصوت مكتوم';b.setAttribute('aria-pressed',String(c4SoundOn))}
$('c4Sound').onclick=()=>{c4SoundOn=!c4SoundOn;localStorage.setItem('saraC4Sound',c4SoundOn?'on':'off');if(c4SoundOn)c4EnableAudio();c4UpdateSoundButton()};
c4UpdateSoundButton();
// Game button opens the shared games lobby; Connect Four opens only from its own game card.
$('c4Close').onclick=()=>{$('c4Overlay').hidden=true;s.emit('gameWatch',{game:'c4',watching:false})};
$('c4Overlay').addEventListener('click',e=>{if(e.target===$('c4Overlay')){$('c4Overlay').hidden=true;s.emit('gameWatch',{game:'c4',watching:false})}});
$('c4Bot').onclick=()=>{c4EnableAudio();s.emit('connect4Bots')};$('c4Join').onclick=()=>{c4EnableAudio();s.emit('connect4Join')};
$('c4Restart').onclick=()=>s.emit('connect4Restart');
$('c4Leave').onclick=()=>s.emit('connect4Leave');
s.on('connect4State',state=>{const old=c4Previous;c4=state;if(old&&!$('c4Overlay').hidden){const oldCount=old.board.flat().filter(Boolean).length,newCount=state.board.flat().filter(Boolean).length;if(state.status==='won'&&old.status!=='won'){c4Play('win');saraCelebrate('c4Overlay',state.players?.[state.winner-1]?.name||'الفائز',c4SoundOn)}else if(state.status==='draw'&&old.status!=='draw')c4Play('draw');else if(newCount>oldCount){c4Play('drop');if(state.players[state.turn]?.id===me&&state.status==='playing'){setTimeout(()=>c4Play('turn'),230);saraTurnAlert('c4Overlay',state.players[state.turn]?.name,c4SoundOn)}}else if(state.status==='playing'&&old.status!=='playing')c4Play('start')}c4Previous=state;renderC4()});
function c4FindWinningFour(grid){if(!Array.isArray(grid))return null;for(let row=0;row<6;row++)for(let col=0;col<7;col++){const color=grid[row]?.[col];if(!color)continue;for(const [dr,dc] of [[0,1],[1,0],[1,1],[1,-1]]){const cells=Array.from({length:4},(_,i)=>[row+i*dr,col+i*dc]);if(cells.every(([y,x])=>y>=0&&y<6&&x>=0&&x<7&&grid[y]?.[x]===color))return cells}}return null}
function renderC4(){
 if(!c4)return;
 const p=c4.players||[],myIndex=p.findIndex(x=>x.id===me);
 $('c4Players').replaceChildren();p.forEach((player,i)=>{const tag=document.createElement('span');tag.className='saraPlayerTag'+(c4.status==='playing'&&c4.turn===i?' activeTurn':'');tag.textContent=(i===0?'🟡 ':'🔴 ');if(player.avatar){const img=document.createElement('img');img.src=player.avatar;img.alt='';img.style.cssText='width:36px;height:36px;object-fit:cover;border-radius:50%;border:2px solid #e5b964;vertical-align:middle;margin-inline:5px';tag.append(img)}tag.append(document.createTextNode(player.name));$('c4Players').append(tag)});
 const status=c4.status;
 $('c4Status').classList.toggle('turnNotice',status==='playing'); $('c4Status').textContent=status==='waiting'?'بانتظار لاعبين للبدء':status==='won'?'🏆 الفائز: '+(p[c4.winner-1]?.name||'اللاعب'):status==='draw'?'تعادل!':'الدور الآن: '+(p[c4.turn]?.name||'اللاعب');
 const humanSeats=p.filter(x=>!x.bot).length,botSeat=p.some(x=>x.bot);$('c4Join').hidden=myIndex!==-1||humanSeats>=2;$('c4Join').textContent=botSeat&&humanSeats===1?'👥 العب مع عضو بدل الكمبيوتر':humanSeats===1?'👥 انضم للاعب الموجود':'👥 العب مع عضو';
 $('c4Restart').hidden=myIndex===-1;
 $('c4Leave').hidden=myIndex===-1;
 const board=$('c4Board');board.replaceChildren();
 for(let row=0;row<6;row++)for(let col=0;col<7;col++){
  const slot=document.createElement('button');slot.type='button';slot.className='c4Slot';
  const piece=c4.board[row][col];if(piece)slot.classList.add(piece===1?'yellow':'red');
  slot.setAttribute('aria-label','العمود '+(col+1));
  slot.disabled=status!=='playing'||myIndex!==c4.turn||!!c4.board[0][col];
  slot.onclick=()=>s.emit('connect4Move',{col});
  board.append(slot);
 }
 const four=status==='won'?c4FindWinningFour(c4.board):null;
 if(four){
  const winnerColor=c4.winner===1?'yellow':'red';
  for(const [row,col] of four)board.children[row*7+col]?.classList.add('c4WinningPiece','c4Winning'+winnerColor);
  requestAnimationFrame(()=>{if(!board.isConnected||!four.every(([row,col])=>board.children[row*7+col]))return;
   board.querySelector('.c4WinningLine')?.remove();
   const first=board.children[four[0][0]*7+four[0][1]],last=board.children[four[3][0]*7+four[3][1]];
   const bounds=board.getBoundingClientRect(),a=first.getBoundingClientRect(),b=last.getBoundingClientRect();
   if(!bounds.width||!bounds.height)return;
   const line=document.createElementNS('http://www.w3.org/2000/svg','svg');line.classList.add('c4WinningLine');line.setAttribute('viewBox','0 0 100 100');line.setAttribute('preserveAspectRatio','none');
   const stroke=document.createElementNS('http://www.w3.org/2000/svg','line');
   stroke.setAttribute('x1',String((a.left+a.width/2-bounds.left)/bounds.width*100));stroke.setAttribute('y1',String((a.top+a.height/2-bounds.top)/bounds.height*100));
   stroke.setAttribute('x2',String((b.left+b.width/2-bounds.left)/bounds.width*100));stroke.setAttribute('y2',String((b.top+b.height/2-bounds.top)/bounds.height*100));
   line.append(stroke);board.append(line);
  });
 }
}

s.on('gameViewers',({game,viewers}={})=>{if(game!=='c4')return;const el=$('c4Viewers');if(!el)return;el.replaceChildren();const title=document.createElement('strong');title.textContent='👁️ المتابعون الآن ('+(viewers?.length||0)+'): ';el.append(title);const names=document.createElement('span');names.textContent=(viewers||[]).map(v=>v.name).join('، ')||'لا يوجد مشاهدون';el.append(names)});

/* Admin-only one-time guest games access */
$('createGuestCode').onclick=()=>s.emit('createGuestCode');s.on('guestCodeCreated',({code,expires})=>{const out=$('guestCodeResult');out.hidden=false;out.replaceChildren();const desc=document.createElement('p');desc.textContent='رمز دخول زائر للألعاب فقط، صالح لمدة 10 دقائق ويُستخدم مرة واحدة:';const val=document.createElement('strong');val.textContent=code;const copy=document.createElement('button');copy.type='button';copy.textContent='📋 نسخ الرمز فقط';copy.onclick=()=>{const link=location.origin+'/guest.html';navigator.clipboard?.writeText(code).then(()=>toast('تم نسخ الرمز فقط')).catch(()=>toast('انسخ الرمز يدويًا'))};out.append(desc,val,copy)});

/* Visible guest pass control for admins */
const guestPassToggle=$('guestPassToggle'),guestPassOverlay=$('guestPassOverlay');function updateGuestPassButton(){guestPassToggle.hidden=true}guestPassToggle.onclick=()=>{guestPassOverlay.hidden=false};$('guestPassClose').onclick=()=>guestPassOverlay.hidden=true;guestPassOverlay.onclick=e=>{if(e.target===guestPassOverlay)guestPassOverlay.hidden=true};$('guestPassCreate').onclick=()=>s.emit('createGuestCode');s.on('adminStatus',updateGuestPassButton);s.on('entered',updateGuestPassButton);s.on('guestCodeCreated',({code})=>{const out=$('guestPassResult');out.replaceChildren();const p=document.createElement('p');p.textContent='الرمز صالح 10 دقائق ويُستخدم مرة واحدة:';const strong=document.createElement('strong');strong.textContent=code;strong.style.cssText='display:block;font-size:26px;letter-spacing:2px;margin:15px';const b=document.createElement('button');b.textContent='📋 نسخ الرمز فقط';b.onclick=()=>{const invitation='🎟️ دعوة لمشاهدة ألعاب مجلس سارة فقط\nالرابط: '+location.origin+'/guest.html\nرمز الدخول: '+code;navigator.clipboard.writeText(code).then(()=>toast('تم نسخ الرمز فقط')).catch(()=>toast('انسخ الرمز يدويًا'))};out.append(p,strong,b)});

$('openUNO').onclick=()=>{if(!me)return toast('ادخل المجلس أولاً');$('gameChooser').hidden=true;s.emit('requestUnoTicket')};s.on('unoTicket',({code})=>{$('unoFrame').src='/uno.html?ticket='+encodeURIComponent(code)+'&name='+encodeURIComponent(me?.name||localStorage.getItem('saraName')||'لاعب');$('unoOverlay').hidden=false});$('unoClose').onclick=()=>{$('unoOverlay').hidden=true;$('unoFrame').src='about:blank'};

$('logout').onclick=()=>{localStorage.removeItem('saraSessionProof');localStorage.removeItem('saraToken');localStorage.removeItem('saraOwnerProof');sessionStorage.removeItem('saraActiveChat');me=null;isAdmin=false;s.disconnect();location.reload()};

// Connect only after all session restoration listeners are registered.
s.connect();

// Preserve reading position even as messages arrive; clear the counter only after reading the bottom.
$('messages').addEventListener('scroll',()=>{if(saraAtBottom($('messages'))&&saraUnread&&window.saraUserIsScrolling){saraMarkRead()}},{passive:true});

// Owner-only game gate. Every game card is visibly locked, and clicks cannot launch a game.
(function(){let gamesEnabled=false,known=false;const renderGate=()=>{const menu=document.getElementById('gamesMenu');if(!menu)return;let b=document.getElementById('ownerGamesGate');if(!b){b=document.createElement('button');b.id='ownerGamesGate';b.type='button';b.style.cssText='margin:8px auto;padding:10px 16px;border-radius:12px;background:#392747;color:#ffdc8a;border:2px solid #e1b55e;font-weight:800;cursor:pointer';menu.querySelector('.c4Head')?.after(b);b.onclick=()=>{if(isOwner&&known)s.emit('setGamesAccess',{enabled:!gamesEnabled})}}b.style.display=isOwner?'block':'none';b.textContent=gamesEnabled?'🔓 الألعاب مفتوحة — اضغط للإغلاق':'🔒 الألعاب مغلقة — اضغط للتفعيل';let notice=document.getElementById('ownerGamesGateNotice');if(!gamesEnabled){if(!notice){notice=document.createElement('div');notice.id='ownerGamesGateNotice';notice.style.cssText='text-align:center;padding:14px;color:#ffdb84;background:#32223e;border:1px solid #b48c46;border-radius:10px;margin:10px';menu.querySelector('.saraLobbyStats')?.after(notice)}notice.textContent='🔒 الألعاب مقفلة بقرار الأونر — لا يمكن الدخول لأي لعبة'}else notice?.remove();menu.querySelectorAll('.saraGameCard').forEach(card=>{const locked=!gamesEnabled;card.style.opacity=locked?'.48':'';card.style.filter=locked?'grayscale(.75)':'';card.style.cursor=locked?'not-allowed':'';card.setAttribute('aria-disabled',String(locked||card.classList.contains('saraGameSoon')));let lock=card.querySelector('.saraGateLock');if(locked&&!lock){lock=document.createElement('span');lock.className='saraGateLock';lock.textContent='🔒 مغلقة';lock.style.cssText='display:inline-block;background:#301f30;border:1px solid #d4a954;color:#ffdf99;padding:4px 9px;border-radius:10px;font-weight:bold';card.append(lock)}if(!locked)lock?.remove()})};document.addEventListener('click',e=>{if(gamesEnabled)return;const target=e.target.closest?.('.saraGameCard,#gamesUNO,#gamesC4,#gamesXO,#gamesBaloot,#gamesCarrom,#openUNO,.salonLaunch');if(target){e.preventDefault();e.stopImmediatePropagation();toast('🔒 الألعاب مغلقة من الأونر')}},true);s.on('gamesAccess',({enabled})=>{known=true;gamesEnabled=!!enabled;renderGate();if(!gamesEnabled){for(const id of ['xoOverlay','c4Overlay','salonOverlay','unoOverlay']){const el=document.getElementById(id);if(el){el.hidden=true;el.style.removeProperty('display')}}for(const id of ['salonFrame','unoFrame']){const frame=document.getElementById(id);if(frame)frame.src='about:blank'}}});s.on('entered',()=>setTimeout(renderGate,0));s.on('roleGranted',()=>setTimeout(renderGate,0));renderGate()})();

// Never let browser scroll anchoring jump a reader to a new message.
(function(){const el=document.getElementById('messages');if(!el)return;el.style.overflowAnchor='none';el.style.scrollBehavior='auto';let readerTop=0,readerMode=false;el.addEventListener('scroll',()=>{readerMode=!saraAtBottom(el);if(readerMode)readerTop=el.scrollTop;else if(window.saraUserIsScrolling&&saraHistoryReady&&!active&&!window.saraEntryReadAnchor&&!window.saraEntryPending)saraMarkRead()},{passive:true});})();
